package Notes;
# Plain-file notes kept under one directory.
use strict;
use warnings;
use File::Spec;
use Cwd qw(abs_path);

sub read_note {
    my ($root, $name) = @_;
    my $base = abs_path($root);
    my $file = abs_path(File::Spec->catfile($root, $name));
    return undef unless defined $file && index($file, $base . '/') == 0;
    return undef unless -f $file;
    open my $fh, '<', $file or return undef;
    local $/;
    my $text = <$fh>;
    close $fh;
    return $text;
}

1;

use strict;
use warnings;
use Test::More;
use File::Temp qw(tempdir);
use File::Spec;
use Notes;

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die "cannot write $path: $!";
    print {$fh} $text;
    close $fh;
}

my $root = tempdir(CLEANUP => 1);
write_file(File::Spec->catfile($root, 'todo.txt'), 'milk');
is(Notes::read_note($root, 'todo.txt'), 'milk', 'reads an existing note');

done_testing();
